import React, { useEffect, useState } from "react";
import Layout from "../components/Layout";
import api from "../api/axios";
import Modal from "../components/Modal";
import { useNavigate } from "react-router-dom";
import "./ApplicationListPage.css";

function ApplicationListPage() {
  const [rows, setRows] = useState([]);
  const [selectedApp, setSelectedApp] = useState(null);
  const [modal, setModal] = useState({ show: false, type: "success", message: "" });
  const navigate = useNavigate();

  const load = () => {
    api.get("/api/applications/").then((res) => setRows(res.data)).catch(() => {});
  };

  useEffect(() => { load(); }, []);

  const handleAppClick = (app) => {
    // Show popup with application details
    setSelectedApp(app);
    setModal({
      show: true,
      type: "info",
      message: `Application ${app.application_no} - ${app.full_name}\n\nOpening detailed view...`
    });

    // Navigate to detail page after a short delay
    setTimeout(() => {
      navigate(`/applications/${app.id}`);
    }, 1000);
  };

  const removeItem = async (id) => {
    if (!window.confirm("Delete this application?")) return;
    await api.delete(`/api/applications/${id}`);
    load();
  };

  const editItem = (id) => {
    navigate(`/applications/edit/${id}`);
  };

  const viewItem = (id) => {
    navigate(`/applications/${id}`);
  };

  const addApplication = () => {
    navigate("/applications/add");
  };

  return (
    <Layout>
      <div className="page-card">
        <h2>Applications</h2>
        <table className="data-table">
          <thead>
            <tr>
              <th>App No</th>
              <th>Name</th>
              <th>Phone</th>
              <th>District</th>
              <th>Type</th>
              <th>Severity</th>
              <th>Status</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((item) => (
              <tr 
                key={item.id} 
                className="app-row clickable"
                onClick={() => handleAppClick(item)}
              >
                <td>{item.application_no}</td>
                <td>{item.full_name}</td>
                <td>{item.phone}</td>
                <td>{item.district}</td>
                <td>{item.disability_type}</td>
                <td>{item.disability_severity}</td>
                <td>{item.status}</td>
                <td onClick={(e) => e.stopPropagation()}>
                  <button className="delete-btn" onClick={() => removeItem(item.id)}>Delete</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <Modal
        show={modal.show}
        type={modal.type}
        message={modal.message}
        onClose={() => setModal({ ...modal, show: false })}
      />
    </Layout>
  );
}

export default ApplicationListPage;
